static prec unsep(prec p)
{
  return
    (
      (prec){
        .pcode = p.pcode,
        .parg = p.parg,
        .sep = 0ULL,
        .pfree_head = p.pfree_head,
        .pnfree = p.pnfree,
        .pnext = p.pnext
      }
    );
}

static void start_epoch(pstate_t t)
{
  uint64_t ep = t.tw[(size_t)(62ULL + (uint64_t)(size_t)17U + 1ULL)];
  if (ep < 0xffffffffffffffffULL)
    t.tw[(size_t)(62ULL + (uint64_t)(size_t)17U + 1ULL)] = ep + 1ULL;
  else
  {
    uint64_t np = (heap_size_u640 - zero_addr1) / 32768ULL;
    uint64_t j = 0ULL;
    uint64_t __anf0 = j;
    bool cond = __anf0 < np;
    while (cond)
    {
      uint64_t vj = j;
      prec p = t.tpm[sz_of(vj)];
      t.tpm[sz_of(vj)] = unsep(p);
      j = vj + 1ULL;
      uint64_t __anf0 = j;
      cond = __anf0 < np;
    }
    t.tw[(size_t)(62ULL + (uint64_t)(size_t)17U + 1ULL)] = 1ULL;
  }
}

static void zero_heads(pstate_t t)
{
  uint64_t e = 62ULL + (uint64_t)(size_t)17U;
  uint64_t j = 0ULL;
  uint64_t __anf0 = j;
  bool cond = __anf0 < e;
  while (cond)
  {
    uint64_t vj = j;
    t.tw[(size_t)vj] = 0ULL;
    j = vj + 1ULL;
    uint64_t __anf0 = j;
    cond = __anf0 < e;
  }
}

static void clear_lists(pstate_t t)
{
  zero_heads(t);
}

typedef struct pinfo_s
{
  uint8_t code;
  uint64_t arg;
  bool swept;
  uint64_t free_head;
  uint64_t nfree;
  uint64_t next;
}
pinfo;

static pinfo read_entry(pstate_t t, uint64_t i)
{
  uint64_t ep = t.tw[(size_t)(62ULL + (uint64_t)(size_t)17U + 1ULL)];
  prec p = t.tpm[sz_of(i)];
  return
    (
      (pinfo){
        .code = p.pcode,
        .arg = p.parg,
        .swept = !(p.pcode == 1U && p.parg < 31ULL) && !(p.pcode == 2U && p.parg > 0ULL) &&
          !(p.pcode == 3U)
        || p.sep == ep,
        .free_head = p.pfree_head,
        .nfree = p.pnfree,
        .next = p.pnext
      }
    );
}

